    /// 📤 Writes the generated SDL to `COMPOSE_GRAPHQL_SCHEMA_OUT`; run via `npx nx build compose/graphql`.
    #[test]
    #[ignore = "writes the generated SDL to COMPOSE_GRAPHQL_SCHEMA_OUT"]
