          const m = JSON.parse(ev.data) as { op: string };
          if (m.op === "ready") {
            clearTimeout(t);
            this.worker.removeEventListener("message", onReady);
            resolve();
          }
        } catch {
          /* ignore */
        }
      };
      this.worker.addEventListener("message", onReady);
      this.worker.postMessage(JSON.stringify({ op: "init", dto }));
    });
  }

