/** @emoji 📣 Subscribe only when {@link KitEventFilter} returns true. */
subscribeFiltered(filterFn: KitEventFilter, handler: (event: KitEvent) => void): Unsubscribe {
  const sub = this.fanout.pipe(filter(filterFn)).subscribe({ next: handler });
  return () => {
    sub.unsubscribe();
  };
}

/** @emoji 📣 Fires only after coalescing dto `Changed` / synthetic `{ Changed: null }` rows. */
subscribeRootInvalidation(handler: () => void): Unsubscribe {
  return this.subscribeFiltered(
    (ev) => typeof ev === "object" && ev !== null && "Changed" in ev && (ev as { Changed?: null }).Changed === null,
    () => handler(),
  );
}

/** @emoji 📣 Kit command lifecycle scalar rows (`composeKitCommand` / `ComposeKitCommand`). */
subscribeComposeKitCommandLifecycle(handler: (row: KitCommandLifecycleEvent["composeKitCommand"]) => void): Unsubscribe {
  return this.subscribeFiltered(
    (ev) => isKitCommandLifecycleEvent(ev),
    (ev) => handler((ev as KitCommandLifecycleEvent).composeKitCommand),
  );
}

private startSubscriptionLoop(): void {
  if (this.gqlLoopRunning) return;
  this.gqlLoopRunning = true;
  void this.transport
    .subscribe(JSON.stringify({ query: KIT_EVENT_STREAM_SUBSCRIPTION }), (eventJson: string) => {
      try {
        const msg = parseJsonValue(eventJson) as KitGraphqlResponseEnvelope<{ eventStream?: JsonValue | null }>;
        if (msg.errors && Array.isArray(msg.errors) && msg.errors.length) return;
        const ev: JsonValue | null | undefined = msg.data?.eventStream;
        if (ev === undefined) return;
        const n = normalizeKitEventFromSubscription(ev);
        if (n) this.fanout.next(n);
        else this.fanout.next(ev as KitEvent);
      } catch {
        /* ignore */
      }
    })
    .catch(() => {
      this.gqlLoopRunning = false;
    });
}

async dispose(): Promise<void> {
  if (this.disposed) return;
  this.disposed = true;
  this.fanout.complete();
  this.transport.dispose();
}

/** @internal One `Query.session.wip.theKit { fullSnapshot }` read to verify GraphQL after WASM init (no local kit cache). */
private async warmGraphqlRead(): Promise<void> {
  await this.materializedLiveJsonForReadScope(theKitReadScope);
}

/** @emoji 🧾 Full DTO for a {@link KitReadScope} via `Query.session.wip.*.store` (`fullSnapshot` scalar); sole full-kit read path (no WASM `snapshot` fallback). */
async materializedLiveJsonForReadScope(scope: KitReadScope): Promise<KitFullDto> {
  this.ensureAlive();
  const { query, variables } = kitSessionWipStoreSelect(scope, "fullSnapshot");
  const data = kitGraphqlData(
    await kitGraphqlRunTyped<JsonValue>(this.graphqlHandle(), { query, variables }, this.timeoutMs),
  ) as JsonValue;
  const raw = gqlDataSessionWipKitStore(data, scope)?.["fullSnapshot"] as JsonValue | undefined;
  const j: JsonValue = typeof raw === "string" ? parseJsonValue(raw) : raw == null ? null : (raw as JsonValue);
  if (j == null || typeof j !== "object" || Array.isArray(j)) {
    throw new Error("kitGraphql: fullSnapshot missing or not an object for the given read scope");
  }
  return composeCoerceKitFullDtoFromJson(j as KitJsonTreeDto);
}

/** @emoji 🧾 Main-line live kit DTO from `Query.session.wip.theKit.full`. */
async theKit(): Promise<KitFullDto> {
  return this.materializedLiveJsonForReadScope(theKitReadScope);
}

async materializeAt(checkpointId: string): Promise<KitFullDto> {
  const idArg = checkpointId.trim();
  if (idArg === "") return this.materializedLiveJsonForReadScope(theKitReadScope);
  return this.materializedLiveJsonForReadScope({ checkpoint: { checkpointId: idArg } });
}

async vcsState(): Promise<JsonObject> {
  const data = kitGraphqlData(
    await this.gqlRun({
      query: `query { session { wip { theKit { id } checkpoints { id parent { id } message time authors hash isRelease changeCount } alternatives { id name draft { id canUndo canRedo openTransaction { id } } } } } }`,
    }),
  ) as JsonValue;
  const wip = (data as { session?: { wip?: JsonObject } }).session?.wip ?? {};
  return { wip } as JsonObject;
}

/** @emoji 🧾 True when any alternative draft reports `canUndo` (VCS draft/transaction stack). */
async canUndo(): Promise<boolean> {
  const v = await this.vcsState();
  const wip = v["wip"] as { alternatives?: readonly { draft?: { canUndo?: boolean } | null }[] } | undefined;
  const alts = wip?.alternatives;
  if (!Array.isArray(alts)) return false;
  for (const a of alts) {
    if (a?.draft?.canUndo) return true;
  }
  return false;
}

/** @emoji 🧾 True when any alternative draft reports `canRedo`. */
async canRedo(): Promise<boolean> {
  const v = await this.vcsState();
  const wip = v["wip"] as { alternatives?: readonly { draft?: { canRedo?: boolean } | null }[] } | undefined;
  const alts = wip?.alternatives;
  if (!Array.isArray(alts)) return false;
  for (const a of alts) {
    if (a?.draft?.canRedo) return true;
  }
  return false;
}

